using System.Collections.Generic;

namespace Lumora.Core.Assets.Poiyomi;

public enum PoiyomiFieldKind { Number, Range, Toggle, Choice, Color, Vector, Texture, Cubemap }

public sealed class PoiyomiField
{
    public string Name = "";
    // Name, or Name#2 and on for a property Poiyomi lists again (alternatives under different conditions).
    public string Key = "";
    public string Label = "";
    public PoiyomiFieldKind Kind;
    public float Min;
    public float Max;
    public bool Whole;
    public int Components;
    // "Label=value|Label=value" for a choice.
    public string Options = "";
    // Shown only while this holds (Poiyomi's expression, PoiyomiCondition).
    public string? Condition;
}

// A category, a section inside one, or a collapsible group inside a section. Items keep Poiyomi's order:
// each is a field or a nested node.
public sealed class PoiyomiNode
{
    public string Label = "";
    public string? Toggle;
    public int Depth;
    // Place in a walk of the whole layout, parents first; Last is the id of the node's last descendant.
    public int Id;
    public int Last;
    public string? Condition;
    public readonly List<object> Items = new();
}

// Poiyomi's own inspector layout: categories, the sections in each with the property that switches the
// feature on, the groups a section folds into, and every property's label and editor. Generated from the
// Properties block; regenerate rather than edit. Parts the port leaves out (AudioLink, LTCGI, light volumes,
// bloomfog) are not listed. -xlinka
public static class PoiyomiSections
{
    private static List<PoiyomiNode>? _categories;
    private static readonly List<PoiyomiNode> _nodes = new();
    private static readonly Dictionary<string, PoiyomiField> _fields = new();

    public static IReadOnlyList<PoiyomiNode> Categories => _categories ??= Index(Build());

    public static PoiyomiField? Field(string key)
    {
        _ = Categories;
        return _fields.TryGetValue(key, out var field) ? field : null;
    }

    public static PoiyomiNode? Node(int id)
    {
        _ = Categories;
        return id >= 0 && id < _nodes.Count ? _nodes[id] : null;
    }

    // Drops nodes that hold no property (a category Poiyomi opens twice, one whose contents the port left out)
    // and numbers the rest.
    private static List<PoiyomiNode> Index(List<PoiyomiNode> categories)
    {
        categories.RemoveAll(c => !Prune(c));
        foreach (var category in categories)
            Walk(category);
        return categories;
    }

    private static bool Prune(PoiyomiNode node)
    {
        node.Items.RemoveAll(item => item is PoiyomiNode child && !Prune(child));
        return node.Items.Count > 0;
    }

    private static void Walk(PoiyomiNode node)
    {
        node.Id = _nodes.Count;
        _nodes.Add(node);
        foreach (var item in node.Items)
        {
            if (item is PoiyomiNode child)
            {
                Walk(child);
            }
            else if (item is PoiyomiField field)
            {
                field.Key = field.Name;
                for (int n = 2; _fields.ContainsKey(field.Key); n++)
                    field.Key = field.Name + "#" + n;
                _fields.Add(field.Key, field);
            }
        }
        node.Last = _nodes.Count - 1;
    }

    private static List<PoiyomiNode> Build()
    {
        var categories = new List<PoiyomiNode>();
        var stack = new Stack<PoiyomiNode>();
        object? last = null;
        void If(string condition)
        {
            if (last is PoiyomiField field)
                field.Condition = condition;
            else if (last is PoiyomiNode node)
                node.Condition = condition;
        }
        void Category(string label, string? toggle)
        {
            stack.Clear();
            var node = new PoiyomiNode { Label = label, Toggle = toggle, Depth = 0 };
            categories.Add(node);
            stack.Push(node);
        }
        void Open(string label, string? toggle)
        {
            if (stack.Count == 0)
                return;
            var node = new PoiyomiNode { Label = label, Toggle = toggle, Depth = stack.Count };
            stack.Peek().Items.Add(node);
            stack.Push(node);
            last = node;
        }
        void Section(string label, string? toggle) => Open(label, toggle);
        void Group(string label, string? toggle) => Open(label, toggle);
        void End()
        {
            if (stack.Count > 1)
                stack.Pop();
        }
        void Add(PoiyomiField field)
        {
            if (stack.Count > 0)
                stack.Peek().Items.Add(field);
            last = field;
        }
        void Number(string n, string l) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Number });
        void Range(string n, string l, float min, float max, bool whole = false) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Range, Min = min, Max = max, Whole = whole });
        void Toggle(string n, string l) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Toggle });
        void Choice(string n, string l, string options) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Choice, Options = options });
        void Color(string n, string l) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Color });
        void Vector(string n, string l, int components) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Vector, Components = components });
        void Texture(string n, string l) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Texture });
        void Cubemap(string n, string l) => Add(new PoiyomiField { Name = n, Label = l, Kind = PoiyomiFieldKind.Cubemap });

