        Group("Bit Grid", null);
        End();
        Group("Summary", null);
        End();
        End();
        Group("Back Faces", null);
        If("(_OutlineStencilType==1)");
        Group("Bit Grid", null);
        End();
        Group("Summary", null);
        End();
        End();
        End();
        End();
        Section("Stencil", null);
        Choice("_StencilType", "Stencil Type", "Simple=0|Front Face vs Back Face=1");
        Range("_StencilRef", "Stencil Reference Value", 0f, 255f);
        Range("_StencilReadMask", "Stencil ReadMask Value", 0f, 255f);
        Range("_StencilWriteMask", "Stencil WriteMask Value", 0f, 255f);
        Choice("_StencilPassOp", "Stencil Pass Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        If("(_StencilType==0)");
        Choice("_StencilFailOp", "Stencil Fail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        If("(_StencilType==0)");
        Choice("_StencilZFailOp", "Stencil ZFail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        If("(_StencilType==0)");
        Choice("_StencilCompareFunction", "Stencil Compare Function", "Disabled=0|Never=1|Less=2|Equal=3|LessEqual=4|Greater=5|NotEqual=6|GreaterEqual=7|Always=8");
        If("(_StencilType==0)");
        Group("Back", null);
        If("(_StencilType==1)");
        Choice("_StencilBackPassOp", "Back Pass Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilBackFailOp", "Back Fail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilBackZFailOp", "Back ZFail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilBackCompareFunction", "Back Compare Function", "Disabled=0|Never=1|Less=2|Equal=3|LessEqual=4|Greater=5|NotEqual=6|GreaterEqual=7|Always=8");
        End();
        Group("Front", null);
        If("(_StencilType==1)");
        Choice("_StencilFrontPassOp", "Front Pass Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilFrontFailOp", "Front Fail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilFrontZFailOp", "Front ZFail Op", "Keep=0|Zero=1|Replace=2|IncrementSaturate=3|DecrementSaturate=4|Invert=5|IncrementWrap=6|DecrementWrap=7");
        Choice("_StencilFrontCompareFunction", "Front Compare Function", "Disabled=0|Never=1|Less=2|Equal=3|LessEqual=4|Greater=5|NotEqual=6|GreaterEqual=7|Always=8");
        End();
        Section("Stencil Calculator", null);
        Toggle("_StencilIsOccluded", "Simulate ZFail");
        Group("Calculator", null);
        If("(_StencilType==0)");
        Group("Bit Grid", null);
        End();
        Group("Summary", null);
        End();
        End();
        Group("Front Faces", null);
        If("(_StencilType==1)");
        Group("Bit Grid", null);
        End();
        Group("Summary", null);
        End();
        End();
        Group("Back Faces", null);
        If("(_StencilType==1)");
        Group("Bit Grid", null);
        End();
        Group("Summary", null);
        End();
        End();
        End();
        End();
        End();
        return categories;
    }
}
